package com.servicedesk360.service;
import com.servicedesk360.dto.common.PageResponse; import com.servicedesk360.dto.notification.NotificationResponse; import com.servicedesk360.entity.Notification; import com.servicedesk360.exception.ResourceNotFoundException; import com.servicedesk360.repository.NotificationRepository; import com.servicedesk360.repository.UserRepository; import com.servicedesk360.websocket.RealtimeEvent; import com.servicedesk360.websocket.RealtimeEventService; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final NotificationRepository repo;private final UserRepository users;private final CurrentUserService current;private final RealtimeEventService realtime;public NotificationService(NotificationRepository r,UserRepository u,CurrentUserService c,RealtimeEventService e){repo=r;users=u;current=c;realtime=e;}@Transactional(readOnly=true) public PageResponse<NotificationResponse> list(Pageable p){var me=current.getRequiredUser();return PageResponse.from(repo.findAllByTenantIdAndUserId(me.tenantId(),me.user().getId(),p).map(NotificationResponse::from));}@Transactional(readOnly=true) public long unreadCount(){var me=current.getRequiredUser();return repo.countByTenantIdAndUserIdAndReadAtIsNull(me.tenantId(),me.user().getId());}@Transactional public NotificationResponse markRead(Long id){var me=current.getRequiredUser();var n=repo.findByIdAndTenantIdAndUserId(id,me.tenantId(),me.user().getId()).orElseThrow(()->new ResourceNotFoundException("Notification not found"));n.setReadAt(java.time.Instant.now());return NotificationResponse.from(n);}@Transactional public Notification create(Long tenantId,Long userId,String type,String title,String message,String refType,Long refId){var user=users.findByIdAndTenantId(userId,tenantId).orElseThrow(()->new ResourceNotFoundException("Notification user not found"));var n=repo.save(new Notification(tenantId,user,type,title,message,refType,refId));realtime.publishUser(user.getEmail(),RealtimeEvent.of("NOTIFICATION_CREATED",tenantId,n.getId(),title));return n;}}
